import sys
input = sys.stdin.read

mod = 998244353
g = 3

def qpow(base, exp):
    result = 1
    base %= mod
    while exp > 0:
        if exp & 1:
            result = (result * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return result

def bit_reverse(array, length):
    j = 0
    for i in range(1, length):
        bit = length >> 1
        while j >= bit:
            j -= bit
            bit >>= 1
        j += bit
        if i < j:
            array[i], array[j] = array[j], array[i]

def transform(array, length, direction):
    bit_reverse(array, length)
    size = 2
    while size <= length:
        root = qpow(g, (mod - 1) // size)
        if direction == -1:
            root = qpow(root, mod - 2)
        for start in range(0, length, size):
            w = 1
            half = size // 2
            for k in range(start, start + half):
                u = array[k]
                v = array[k + half] * w % mod
                array[k] = (u + v) % mod
                array[k + half] = (u - v + mod) % mod
                w = w * root % mod
        size <<= 1
    if direction == -1:
        inv_len = qpow(length, mod - 2)
        for i in range(length):
            array[i] = array[i] * inv_len % mod

def main():
    data = list(map(int, input().split()))
    n, m = data[0], data[1]
    halfN = n // 2
    len_power = 1
    while len_power < (9 * halfN + 1):
        len_power <<= 1
    array = [0] * len_power
    for x in data[2:2 + m]:
        array[x] = 1
    transform(array, len_power, 1)
    for i in range(len_power):
        if array[i] != 0:
            array[i] = qpow(array[i], halfN) % mod
    transform(array, len_power, -1)
    total = 0
    for i in range(len_power):
        total = (total + array[i] * array[i]) % mod
    print(total)

if __name__ == "__main__":
    main()

